//! Tier-1 fixture parity for the OpenAPI converter.
//!
//! Endpoint `examples` are stripped from BOTH sides before comparison — code
//! samples are generated by the JS post-pass (@readme/oas-to-snippet) and are
//! covered by the through-shim vitest tier. Component-schema examples ARE
//! Rust-generated and stay in the comparison.
//!
//! Skip-list (covered by tier 2): fixtures whose oracle embeds JS-closure
//! plugin post-processing — -2.complex.openai (uniformOpenAIMeta),
//! 5.xdocs.sidebar (uniformPluginXDocsSidebar).

use serde_json::Value;
use xyd_openapi::oap_schema_to_references_from_file;
use xyd_uniform::canon;

fn strip_endpoint_examples(refs: &mut Value) {
    let Some(arr) = refs.as_array_mut() else {
        return;
    };
    for r in arr {
        let is_component = r.get("type").and_then(|t| t.as_str()) == Some("rest_component_schema");
        if !is_component {
            if let Some(obj) = r.as_object_mut() {
                obj.remove("examples");
            }
        }
    }
}

fn run_case(name: &str) {
    let fixtures = xyd_parity::fixtures_dir(env!("CARGO_MANIFEST_DIR"), "xyd-openapi");
    let case = fixtures.join(name);
    let input = ["input.yaml", "input.json"]
        .iter()
        .map(|f| case.join(f))
        .find(|p| p.exists())
        .unwrap_or_else(|| panic!("{name}: no input.(yaml|json)"));

    let refs = oap_schema_to_references_from_file(input.to_str().unwrap(), None)
        .unwrap_or_else(|e| panic!("{name}: convert failed: {e}"));
    let mut actual = serde_json::to_value(&refs).expect("serialize");
    strip_endpoint_examples(&mut actual);

    let mut oracle = xyd_parity::read_oracle(&case);
    strip_endpoint_examples(&mut oracle);

    if std::env::var("XYD_PARITY_DUMP").as_deref() == Ok("1") {
        std::fs::write(
            case.join("output.rust.json"),
            serde_json::to_string_pretty(&actual).unwrap(),
        )
        .unwrap();
    }

    let diffs = canon::diff_paths(&actual, &oracle, 12);
    assert!(
        diffs.is_empty(),
        "{name}: PARITY FAILED — first divergences:\n{}",
        diffs
            .iter()
            .map(|(p, a, b)| format!(
                "  at {p}\n    rust:   {}\n    oracle: {}",
                truncate(&a.to_string()),
                truncate(&b.to_string())
            ))
            .collect::<Vec<_>>()
            .join("\n")
    );
}

fn truncate(s: &str) -> String {
    if s.len() <= 220 {
        s.to_string()
    } else {
        let mut end = 220;
        while !s.is_char_boundary(end) {
            end -= 1;
        }
        format!("{}…", &s[..end])
    }
}

macro_rules! parity_case {
    ($test:ident, $name:literal) => {
        #[test]
        fn $test() {
            run_case($name);
        }
    };
}

parity_case!(random, "-3.random");
parity_case!(basic, "1.basic");
parity_case!(more, "2.more");
parity_case!(multiple_responses, "3.multiple-responses");
parity_case!(xdocs_code_languages, "5.xdocs.codeLanguages");
parity_case!(code_samples, "6.codeSamples");
parity_case!(examples_case, "7.examples");
parity_case!(enums, "8.enums");
